// Checked-in generated files. A generator module computes `outputs`, a map of
// repository-relative path to file text; this writes them, or with --check
// reports the files that differ from what the generator produces.

import fs from "node:fs";
import path from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";
import { Logger } from "../sdk/src/blgr/index.ts";

const ROOT = path.dirname(path.dirname(fileURLToPath(import.meta.url)));

/**
 * The opening comment of a generated file: the generator that writes it and
 * every input it is derived from, behind the file's line-comment marker.
 */
export function generatedHeader(generator, inputs, comment = "//") {
  return `${comment} GENERATED by ${generator}. Do not edit by hand.\n${comment} Inputs: ${inputs.join(", ")}.\n`;
}

/** The paths in `outputs` whose file is missing or differs. */
function staleOutputs(outputs) {
  return [...outputs].flatMap(([relative, text]) => {
    const target = path.join(ROOT, relative);
    return fs.existsSync(target) && fs.readFileSync(target, "utf8") === text ? [] : [relative];
  });
}

/** `[--check]` is the only argument a generator takes. */
export function checkRequested(args = process.argv.slice(2)) {
  if (args.some((arg) => arg !== "--check")) throw new Error(`usage: node ${path.relative(ROOT, process.argv[1])} [--check]`);
  return args.length > 0;
}

/**
 * Bring the files in `outputs` up to date and return the paths that were
 * stale. With `check`, write nothing.
 */
export function emit(outputs, { check }) {
  const stale = staleOutputs(outputs);
  if (!check) {
    for (const relative of stale) {
      const target = path.join(ROOT, relative);
      fs.mkdirSync(path.dirname(target), { recursive: true });
      fs.writeFileSync(target, outputs.get(relative));
    }
  }
  return stale;
}

/** Log what `emit` found and fail a check that found stale files. */
export async function report(stale, { check, regenerate }) {
  const logger = new Logger("info");
  await logger.open();
  if (stale.length === 0) {
    logger.info("generated files are up to date");
  } else if (check) {
    for (const relative of stale) logger.error(`${relative} is stale or missing`);
    logger.error(`regenerate with \`${regenerate}\``);
    process.exitCode = 1;
  } else {
    for (const relative of stale) logger.info(`wrote ${relative}`);
  }
}

/** The command line of one generator run directly: `node <generator> [--check]`. */
export async function runGenerator(meta, outputs) {
  if (!process.argv[1] || meta.url !== pathToFileURL(path.resolve(process.argv[1])).href) return;
  const check = checkRequested();
  await report(emit(outputs, { check }), { check, regenerate: `node ${path.relative(ROOT, process.argv[1])}` });
}
